// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(uint256 noise, address actor) public {
        // Before any initialization/pause action has occurred, the stored paused
        // flag is false (its default value), so the reference contract must report
        // paused() == false for ANY input; the mutant unconditionally returns true.
        vm.prank(actor);
        bool p = c.paused();
        assertTrue(p == false, "paused() must be false when contract is not paused");
    }
}
